{
  "status": "SUPPORTED",
  "task_summary": "Identify components, perform fastening, and place tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the task occurs and where the tool is left.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "table",
          "desk"
        ],
        "required_properties": [
          "flat surface",
          "stable"
        ]
      },
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The object requiring a fastening operation.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "assembly",
          "device",
          "tray"
        ],
        "required_properties": [
          "needs fastening",
          "has interface"
        ]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The part required to complete the fastening.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "part",
          "block",
          "piece"
        ],
        "required_properties": [
          "fits target"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to secure the component.",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "tool",
          "implement",
          "device"
        ],
        "required_properties": [
          "can fasten"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "located_on_initial",
        "relation": "LocatedOn",
        "participant_roles": [
          "compatible_component",
          "workbench"
        ],
        "required": true
      },
      {
        "id": "attached_to_final",
        "relation": "AttachedTo",
        "participant_roles": [
          "compatible_component",
          "fastening_target"
        ],
        "required": true
      },
      {
        "id": "resting_on_final",
        "relation": "RestingOn",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_component",
        "operation": "LocateComponent",
        "participant_roles": [
          "compatible_component",
          "fastening_target"
        ],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "Fasten",
        "participant_roles": [
          "compatible_component",
          "fastening_target",
          "fastening_tool"
        ],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "PlaceTool",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        { "label": "Wooden table with drawers", "visual_description": "Central wooden table with two blue drawers and a cabinet behind it." }
      ],
      "fastening_target": [
        { "label": "Black tray with blocks", "visual_description": "Black rectangular tray on the table surface containing yellow and blue blocks." }
      ],
      "compatible_component": [
        { "label": "Yellow block in gripper", "visual_description": "Yellow block held by the robot arm in the third view." },
        { "label": "Blocks on tray", "visual_description": "Yellow and blue blocks sitting on the black tray." }
      ],
      "fastening_tool": [
        { "label": "None visible", "visual_description": "No obvious screwdriver or hammer seen; may be inside storage." }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "Blue cabinet",
        "visual_description": "Tall blue cabinet standing against the back wall.",
        "reason": "Closed storage structure, likely contains tools or spare parts."
      },
      {
        "id": "drawer_left",
        "label": "Left drawer",
        "visual_description": "Blue drawer under the left side of the table.",
        "reason": "Closed drawer, likely contains small tools or components."
      },
      {
        "id": "drawer_right",
        "label": "Right drawer",
        "visual_description": "Blue drawer under the right side of the table.",
        "reason": "Closed drawer, likely contains small tools or components."
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawer_left",
      "drawer_right"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
